struct ValidationResult {
    bool isValid;
    std::vector<std::string> errors;
    double entropyScore;
};

class CompiledPolicyValidator {
private:
    std::string password;

    bool hasRepeatedChars(const std::string& pwd) {
        if (pwd.length() < 3) return false;
        for (size_t i = 0; i < pwd.length() - 2; ++i) {
            if (pwd[i] == pwd[i+1] && pwd[i] == pwd[i+2]) return true;
        }
        return false;
    }

    bool hasSequentialChars(const std::string& pwd) {
        if (pwd.length() < 3) return false;
        std::vector<std::string> sequences = {
            "01234567890", "qwertyuiop", "asdfghjkl", "zxcvbnm", "abcdefghijklmnopqrstuvwxyz"
        };
        for (size_t i = 0; i < pwd.length() - 2; ++i) {
            std::string tri = pwd.substr(i, 3);
            for (const auto& seq : sequences) {
                if (seq.find(tri) != std::string::npos) return true;
                std::string rev_seq = seq;
                std::reverse(rev_seq.begin(), rev_seq.end());
                if (rev_seq.find(tri) != std::string::npos) return true;
            }
        }
        return false;
    }

    bool isCommonPassword(const std::string& pwd) {
        static const std::unordered_set<std::string> commonPasswords = {
            "password", "123456", "123456789", "12345", "12345678", "111111",
            "1234567", "sunshine", "qwerty", "iloveyou", "admin", "welcome", "letmein"
        };
        if (commonPasswords.find(pwd) != commonPasswords.end()) return true;
        std::string base = pwd;
        while (!base.empty() && (std::isdigit((unsigned char)base.back()) || std::ispunct((unsigned char)base.back()))) base.pop_back();
        if (!base.empty() && commonPasswords.find(base) != commonPasswords.end()) return true;
        return false;
    }

    int calculatePoolSize(int uppers, int lowers, int digits, int specials) {
        int pool = 0;
        if (uppers > 0) pool += 26;
        if (lowers > 0) pool += 26;
        if (digits > 0) pool += 10;
        if (specials > 0) pool += 32;
        return pool;
    }

public:
    CompiledPolicyValidator(const std::string& pwd) : password(pwd) {}

    ValidationResult validate() {
        ValidationResult result;
        result.isValid = true;

        int upperCount = 0, lowerCount = 0, digitCount = 0, specialCount = 0, spaceCount = 0;
        for (char ch : password) {
            if (std::isupper(ch)) upperCount++;
            else if (std::islower(ch)) lowerCount++;
            else if (std::isdigit(ch)) digitCount++;
            else if (std::isspace(ch)) spaceCount++;
            else specialCount++;
        }

        int pool = calculatePoolSize(upperCount, lowerCount, digitCount, specialCount);
        if (pool > 0) {
             result.entropyScore = password.length() * (std::log(pool) / std::log(2));
        } else {
             result.entropyScore = 0;
        }

        // Advanced Checks (Leet-speak normalization, dictionary, sequential)
        std::string normalizedPwd = password;
        for (char& c : normalizedPwd) {
            c = std::tolower(c);
            if (c == '@') c = 'a';
            else if (c == '0') c = 'o';
            else if (c == '3') c = 'e';
            else if (c == '1') c = 'i';
            else if (c == '5') c = 's';
            else if (c == '7') c = 't';
            else if (c == '$') c = 's';
            else if (c == '!') c = 'i';
        }

        if (hasRepeatedChars(normalizedPwd)) {
            result.isValid = false;
            result.errors.push_back("[REJECTED] Password contains repeated characters (e.g., aaa).");
        }
        if (hasSequentialChars(normalizedPwd)) {
            result.isValid = false;
            result.errors.push_back("[REJECTED] Password contains sequential or keyboard-walk characters.");
        }
        if (isCommonPassword(normalizedPwd)) {
            result.isValid = false;
            result.errors.push_back("[REJECTED] Password is in the dictionary of common passwords.");
        }

        // --- COMPILED CONSTRAINTS INJECTION ---
        if (password.length() < 8) {
            result.isValid = false;
            result.errors.push_back("[REJECTED] Password is too short. Minimum length is 8.");
        }
        if (upperCount > 0) {
            result.isValid = false;
            result.errors.push_back("[REJECTED] Uppercase letter (A-Z) is forbidden.");
        }
        if (digitCount > 0) {
            result.isValid = false;
            result.errors.push_back("[REJECTED] Numeric digit (0-9) is forbidden.");
        }
        if (spaceCount == 0) {
            result.isValid = false;
            result.errors.push_back("[REJECTED] Missing required space character.");
        }
        // --------------------------------------

        return result;
    }
};

